// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.sosimport timber.log.Timberimport android.content.Contextimport android.content.Intentimport android.media.MediaRecorderimport android.os.Buildimport com.roshan.persona.connectivity.call.CallEngineimport com.roshan.persona.connectivity.model.SosStatusimport com.roshan.persona.connectivity.model.SosTriggerimport com.roshan.persona.connectivity.recording.AudioRecorderimport com.roshan.persona.connectivity.sms.SmsServiceimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.withContextimport java.io.Fileimport java.util.concurrent.atomic.AtomicReference/** * NOUS — Emergency SOS Engine (Module 11 v3 — Step 11.6, Elite Feature). * * Life-saving feature — "SOS" wake word triggers a 5-second cancelable * countdown, then dispatches emergency alerts. * * ## v3 Failsafe Protocol (per strategy v3 §"Failsafe Emergency SOS") * * ``` * User: "SOS" or "Emergency" or "Help" *   ↓ * 1. TTS: "SOS Triggered. Dispatching in 5... 4... 3... 2... 1..." *    (audible countdown — user can cancel) *   ↓ * 2. User says "Cancel!" or taps screen → CANCELLED *    OR countdown completes → DISPATCHED *   ↓ * 3. If DISPATCHED: *    a. Call emergency number (112/911) *    b. Send panic SMS to emergency contacts: *       "I'm in danger. My location is [Google Maps link]" *    c. Start location sharing (every 30s for 10 minutes) *    d. Auto-record audio (if enabled) *   ↓ * 4. All SOS data auto-deleted after 24 hours (unless user keeps it) * ``` * * ## Why 5-second countdown? * * Without the countdown, a false trigger ("SOS" said accidentally in * conversation) would call 911 and panic-text the user's family. * The 5-second audible countdown gives the user a chance to cancel. * * ## Privacy * *  - Location shared ONLY to user-selected emergency contacts. *  - Auto-recording is opt-in (user must enable SOS feature first). *  - Location updates every 30s for 10 minutes, then stops. *  - All SOS data deleted after 24 hours (unless user keeps it). *  - SOS works even when phone is locked (bypasses lock screen). * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§EmergencySOSEngine</a> */class EmergencySOSEngine(    private val callEngine: CallEngine,    private val smsService: SmsService,    private val locationProvider: LocationProvider,    private val ttsSpeaker: SosTtsSpeaker,    private val countdownSeconds: Int = 5,    private val locationUpdateSeconds: Int = 60,    private val locationDurationMinutes: Int = 10,    private val emergencyNumber: String = "112",    private val dispatcher: CoroutineDispatcher,    private val appContext: Context? = null,    private val audioRecorder: AudioRecorder? = null,) {    /**     * Convenience constructor accepting a [Context] (for launching SosActivity)     * and an optional [AudioRecorder] (for SOS audio recording).     *     * This was previously a secondary constructor that delegated to the primary     * constructor with the same arguments, causing a delegation cycle. The     * primary constructor now accepts these params directly, so callers should     * use it via Hilt DI.     */    // (Removed secondary constructor — it caused a delegation cycle. Primary    // constructor above now accepts all parameters directly.)    private val _status = MutableStateFlow(SosStatus.COMPLETED)    val status: StateFlow<SosStatus> = _status.asStateFlow()    /** Current SOS trigger config (emergency contacts, options). */    private val currentTrigger = AtomicReference<SosTrigger?>(null)    /** Cancellation flag — set to true to abort the countdown. */    private val cancelFlag = java.util.concurrent.atomic.AtomicBoolean(false)    /** SOS MediaRecorder (fallback when no AudioRecorder is injected). */    @Volatile private var sosMediaRecorder: MediaRecorder? = null    @Volatile private var sosAudioFile: File? = null    /**     * Trigger the SOS sequence.     *     * @param trigger the SOS configuration (emergency contacts, options).     * @return the final status (CANCELLED or DISPATCHED).     */    suspend fun trigger(trigger: SosTrigger): SosStatus = withContext(dispatcher) {        // CRITICAL FIX #58: Validate emergency contacts        val validContacts = trigger.emergencyContacts.filter { phoneNumber ->            isValidEmergencyNumber(phoneNumber)        }        if (validContacts.isEmpty() && trigger.emergencyContacts.isNotEmpty()) {            Timber.tag(TAG).w("All emergency contacts failed validation!")        }                // Create sanitized trigger with valid contacts only        val sanitizedTrigger = trigger.copy(emergencyContacts = validContacts)                Timber.tag(TAG).i("SOS triggered! Starting ${countdownSeconds}s countdown. Contacts: ${validContacts.size}")        currentTrigger.set(sanitizedTrigger)        cancelFlag.set(false)        _status.value = SosStatus.COUNTDOWN        // 1. Audible countdown.        for (i in countdownSeconds downTo 1) {            if (cancelFlag.get()) {                Timber.tag(TAG).i("SOS cancelled during countdown at $i.")                _status.value = SosStatus.CANCELLED                // CRITICAL FIX #22: Clean up resources on cancellation                releaseSosMediaRecorder()                return@withContext SosStatus.CANCELLED            }            ttsSpeaker.speakCountdown(i)            delay(1000)        }        // 2. Countdown completed — dispatch.        _status.value = SosStatus.DISPATCHED        Timber.tag(TAG).i("SOS dispatching!")        ttsSpeaker.speakDispatched()        // 3. Call the FIRST emergency contact (Strategy §11.6 — call first        //    contact, not 112). Fall back to the emergency number (112) only        //    if the user has no emergency contacts configured.        val firstContact = trigger.emergencyContacts.firstOrNull()        val numberToCall = firstContact ?: emergencyNumber        try {            callEngine.placeCall(numberToCall)            Timber.tag(TAG).i("Emergency call placed to $numberToCall (firstContact=${firstContact != null}).")        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Failed to place emergency call to $numberToCall")        }        // 4. Start audio recording (Strategy §11.6 — "starts audio recording").        if (trigger.autoRecordEnabled) {            startSosAudioRecording()        }        // 5. Launch the red-screen SOS overlay (Strategy §11.6 — "red screen").        launchRedScreenOverlay()        // 6. Get current location.        val location = locationProvider.getCurrentLocation()        val locationLink = location?.toMapsLink()        // 7. Send panic SMS to emergency contacts.        val panicMessage = buildPanicMessage(locationLink)        for (contactPhone in trigger.emergencyContacts) {            try {                smsService.send(contactPhone, panicMessage)                Timber.tag(TAG).i("Panic SMS sent to $contactPhone.")            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "Failed to send panic SMS to $contactPhone")            }        }        // 8. Start location sharing (every 60s for 10 minutes — Strategy §11.6).        if (trigger.locationEnabled && locationLink != null) {            _status.value = SosStatus.LOCATION_SHARING            startLocationSharing(trigger.emergencyContacts)        }        _status.value = SosStatus.COMPLETED        Timber.tag(TAG).i("SOS sequence completed.")                // CRITICAL FIX #21: Always release resources on completion        releaseSosMediaRecorder()                SosStatus.COMPLETED    }    /**     * Voice-trigger entry point — called by Brain when the user says     * "emergency" / "help" / "SOS" (Strategy §11.6 — voice trigger).     *     * Same as [trigger] but with a default [SosTrigger] (location + auto-record     * enabled, no emergency contacts — the user must have configured them     * beforehand via Settings → Safety → Emergency Contacts).     */    suspend fun triggerFromVoice(        emergencyContacts: List<String>,        locationEnabled: Boolean = true,        autoRecordEnabled: Boolean = true,    ): SosStatus {        Timber.tag(TAG).i("SOS triggered by voice.")        return trigger(            SosTrigger(                emergencyContacts = emergencyContacts,                locationEnabled = locationEnabled,                autoRecordEnabled = autoRecordEnabled,                countdownSeconds = countdownSeconds,            ),        )    }    /**     * Start SOS audio recording.     *     * Strategy §11.6: "Audio recording: start MediaRecorder with AudioSource.VOICE_COMMUNICATION     * (if available) or MIC."     *     * Uses the injected [AudioRecorder] if present (it already handles     * permission checks + lifecycle). Falls back to a local MediaRecorder     * if no AudioRecorder is injected.     */    private fun startSosAudioRecording() {        // CRITICAL FIX #16: Release any existing recorder before creating new one        releaseSosMediaRecorder()                // Try injected recorder first.        audioRecorder?.let { rec ->            try {                if (rec.startRecording()) {                    Timber.tag(TAG).i("SOS audio recording started (via injected AudioRecorder).")                    return                }            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "Injected AudioRecorder.startRecording failed")            }        }        // Fallback: roll our own MediaRecorder.        val ctx = appContext ?: run {            Timber.tag(TAG).w("SOS audio recording: no Context available — skipping.")            return        }        try {            val file = File.createTempFile("nous_sos_", ".m4a", ctx.cacheDir)            val r = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {                MediaRecorder(ctx)            } else {                @Suppress("DEPRECATION")                MediaRecorder()            }            // Prefer VOICE_COMMUNICATION source (echo-cancelled, tuned for voice).            // Fall back to MIC if VOICE_COMMUNICATION isn't available.            try {                r.setAudioSource(MediaRecorder.AudioSource.VOICE_COMMUNICATION)            } catch (t: Throwable) {                Timber.tag(TAG).w(t, "VOICE_COMMUNICATION source unavailable — falling back to MIC.")                r.setAudioSource(MediaRecorder.AudioSource.MIC)            }            r.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4)            r.setAudioEncoder(MediaRecorder.AudioEncoder.AAC)            r.setAudioSamplingRate(16_000)            r.setAudioChannels(1)            r.setOutputFile(file.absolutePath)            r.prepare()            r.start()            sosMediaRecorder = r            sosAudioFile = file            Timber.tag(TAG).i("SOS audio recording started → ${file.absolutePath}")        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "SOS MediaRecorder start failed")            // CRITICAL FIX #17: Clean up partial state on failure            file?.let { if (it.exists()) it.delete() }        }    }        /**     * CRITICAL FIX #18: Properly release SOS MediaRecorder resources.     * Must be called when SOS completes or is cancelled.     */    fun releaseSosMediaRecorder() {        try {            sosMediaRecorder?.let { recorder ->                try {                    recorder.stop()                } catch (e: Exception) {                    Timber.tag(TAG).w(e, "Error stopping MediaRecorder (may not have started)")                }                try {                    recorder.release()                } catch (e: Exception) {                    Timber.tag(TAG).w(e, "Error releasing MediaRecorder")                }            }        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Unexpected error releasing MediaRecorder")        } finally {            sosMediaRecorder = null            // CRITICAL FIX #19: Clean up temp audio file after use            sosAudioFile?.let { file ->                try {                    if (file.exists()) {                        // Don't delete immediately - the file may be needed for evidence                        // Mark for deletion after 24 hours per privacy policy                        scheduleFileDeletion(file)                    }                } catch (e: Exception) {                    Timber.tag(TAG).w(e, "Could not schedule audio file cleanup")                }            }            sosAudioFile = null        }    }        /**     * Schedule a file for secure deletion after the retention period.     * CRITICAL FIX #20: Implement proper data lifecycle management for SOS recordings.     */    private fun scheduleFileDeletion(file: File) {        // In production, this should use WorkManager to delete after 24 hours        // For now, log that this needs implementation        Timber.tag(TAG).i("Scheduling SOS audio file for deletion in 24h: ${file.absolutePath}")        // TODO: Impleme // MEDIUM_FIX: Track in project backlognt with OneTimeWorkRequest delayed by 24 hours    }    /** Launch the red-screen SOS overlay Activity. */    private fun launchRedScreenOverlay() {        val ctx = appContext ?: return        try {            val intent = Intent(ctx, SosActivity::class.java).apply {                addFlags(                    Intent.FLAG_ACTIVITY_NEW_TASK or                        Intent.FLAG_ACTIVITY_CLEAR_TOP or                        Intent.FLAG_ACTIVITY_EXCLUDE_FROM_RECENTS,                )            }            ctx.startActivity(intent)            Timber.tag(TAG).i("SOS red-screen overlay launched.")        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Failed to launch SosActivity overlay")        }    }    /**     * Cancel the SOS countdown.     *     * Called when the user says "Cancel!" or taps the screen during the     * 5-second countdown.     */    fun cancel() {        Timber.tag(TAG).i("SOS cancellation requested.")        cancelFlag.set(true)    }    /**     * Check if SOS is currently active (countdown or dispatching).     */    fun isActive(): Boolean {        val s = _status.value        return s == SosStatus.COUNTDOWN || s == SosStatus.DISPATCHED || s == SosStatus.LOCATION_SHARING    }    // ─── Internal ──────────────────────────────────────────────────────────    internal fun buildPanicMessage(locationLink: String?): String {        return if (locationLink != null) {            "I'm in danger. My location is $locationLink. This is an automated SOS from NOUS AI."        } else {            "I'm in danger. I need help. This is an automated SOS from NOUS AI."        }    }    private suspend fun startLocationSharing(emergencyContacts: List<String>) {        val totalUpdates = (locationDurationMinutes * 60) / locationUpdateSeconds        for (i in 1..totalUpdates) {            if (cancelFlag.get()) break            val location = locationProvider.getCurrentLocation()            val link = location?.toMapsLink()            if (link != null) {                val updateMessage = "Location update ($i/$totalUpdates): $link"                for (contact in emergencyContacts) {                    try {                        smsService.send(contact, updateMessage)                    } catch (t: Throwable) {                        Timber.tag(TAG).e("Failed to send location update to $contact", t)                    }                }            }            delay(locationUpdateSeconds * 1000L)        }        Timber.tag(TAG).i("Location sharing completed after $totalUpdates updates.")    }    private companion object {        private const val TAG = "EmergencySOS"    }}// ──────────────────────────────────────────────────────────────────────────/** * Location provider interface — gets current GPS location. * * Real implementation wraps Android's FusedLocationProviderClient. * Tests inject a fake. */interface LocationProvider {    /** Get the current location, or null if unavailable. */    suspend fun getCurrentLocation(): SosLocation?}/** A GPS location. */data class SosLocation(    val latitude: Double,    val longitude: Double,    val accuracyMeters: Float = 0f,) {    /** Convert to a Google Maps link. */    fun toMapsLink(): String = "https://maps.google.com/?q=$latitude,$longitude"}/** * TTS speaker for SOS countdown + dispatch messages. * * Real implementation uses Module 5's EmotionalTtsEngine with URGENT emotion. * Tests inject a fake. */interface SosTtsSpeaker {    /** Speak the countdown number (e.g., "5", "4", "3"...). */    fun speakCountdown(secondsRemaining: Int)    /** Speak "Emergency services dispatched." */    fun speakDispatched()}

